/** Where a function's dependency list came from. */
export type DependencySource = 'manifest' | 'autoinstall' | 'bundled' | 'none';
export type DependencyInfo = {
    dependencySource: DependencySource;
    dependencyCount: number;
    /** Declared versions */
    dependencies?: Record<string, string>;
    /** Source files the Arc treeshaker parsed - autoinstall only */
    parsedFileCount?: number;
};
/** The package.json Architect generates during autoinstall. */
export type AutoInstallManifest = {
    dependencies?: Record<string, string>;
    _parsed?: string[];
};
/**
 * Read and delete the manifest Architect generated during autoinstall.
 * Arc moves it to `node_modules/_arc-autoinstall/` after the install.
 * Has a timestamp, so it must be deleted to avoid hash changes on every deploy.
 */
export declare function takeAutoInstallManifest(installDir: string): Promise<AutoInstallManifest | undefined>;
/**
 * Describe a function's dependencies from the manifest that declared them.
 * The user's own package.json wins. Otherwise the Architect autoinstall manifest is used.
 */
export declare function getDependencyInfo({ sourceDir, autoInstall, bundled, }: {
    sourceDir: string;
    autoInstall?: AutoInstallManifest;
    bundled: boolean;
}): Promise<DependencyInfo>;
